import { createFileRoute } from "@tanstack/react-router";
import type {} from "@tanstack/react-start";
import sitemapPaths from "@/data/sitemapPaths.json";
import { allHomeProfilePaths } from "@/data/facultyRoster";
import { SITE_URL } from "@/lib/seo";

// Every indexable page's canonical path, generated by crawling the site with
// `node scripts/generate-sitemap.mjs` — re-run it after adding or removing
// pages. Redirecting URLs, noindex stubs and duplicates are already excluded.
// Faculty/staff profiles come straight from the roster: staff profiles have
// no inbound links, so the crawl can't find them.
const PATHS = [...new Set([...(sitemapPaths as string[]), ...allHomeProfilePaths()])].sort((a, b) =>
  a === "/" ? -1 : b === "/" ? 1 : a.localeCompare(b),
);

type ChangeFreq = "weekly" | "monthly" | "yearly";

interface SitemapRule {
  test: RegExp;
  changefreq: ChangeFreq;
  priority: string;
}

// First match wins.
const RULES: SitemapRule[] = [
  { test: /^\/$/, changefreq: "weekly", priority: "1.0" },
  { test: /^\/(admissions|departments)$/, changefreq: "monthly", priority: "0.9" },
  { test: /^\/(about|placements|contact)$/, changefreq: "monthly", priority: "0.8" },
  { test: /^\/(upcoming-events|circulars|careers)$/, changefreq: "weekly", priority: "0.7" },
  { test: /^\/departments\/[^/]+\/faculty\/[^/]+$/, changefreq: "monthly", priority: "0.5" },
  { test: /^\/departments\/[^/]+\/(faculty|about[^/]*|[a-z]+-about-the-department)$/, changefreq: "monthly", priority: "0.8" },
  { test: /^\/departments\//, changefreq: "monthly", priority: "0.6" },
  { test: /^\/(about|campus-life|research|resources)\//, changefreq: "monthly", priority: "0.6" },
  { test: /^\/p\/(event|.*fdp|.*workshop)/, changefreq: "yearly", priority: "0.4" },
  { test: /^\/p\//, changefreq: "monthly", priority: "0.5" },
  { test: /^\/(privacy-policy)$/, changefreq: "yearly", priority: "0.3" },
  { test: /.*/, changefreq: "monthly", priority: "0.6" },
];

const escapeXml = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;");

export const Route = createFileRoute("/sitemap.xml")({
  server: {
    handlers: {
      GET: async () => {
        const urls = PATHS.map((path) => {
          const rule = RULES.find((r) => r.test.test(path))!;
          return [
            `  <url>`,
            `    <loc>${escapeXml(SITE_URL + encodeURI(path))}</loc>`,
            `    <changefreq>${rule.changefreq}</changefreq>`,
            `    <priority>${rule.priority}</priority>`,
            `  </url>`,
          ].join("\n");
        });

        const xml = [
          `<?xml version="1.0" encoding="UTF-8"?>`,
          `<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">`,
          ...urls,
          `</urlset>`,
        ].join("\n");

        return new Response(xml, {
          headers: {
            "Content-Type": "application/xml",
            "Cache-Control": "public, max-age=3600",
          },
        });
      },
    },
  },
});
